        width: 100%;
        background-color: #e0e0e0;
        border-radius: 5px;
        height: 10px;
        margin-top: 5px;
        overflow: hidden;
      }
      .progress-bar {
        height: 100%;
        background-color: var(--primary-color);
        transition: width 0.5s ease-in-out;
        border-radius: 5px;
      }
    </style>
</head>
<body>
    <div class="status-bar-data-container">$1</div>
    <div class="status-bar-container">
      <div class="status-bar-header">江湖人脉</div>
      <div class="status-bar-content">
        <div class="no-data">暂无故人...</div>
      </div>
    </div>
    <script>
    document.addEventListener('DOMContentLoaded', () => {
      const dataContainer = document.querySelector('.status-bar-data-container');
      const contentArea = document.querySelector('.status-bar-content');
      if (!dataContainer || !contentArea) return;

      function parseData(text) {
        const data = {};
        const blockRegex = /\[([^\]_]+)\]([\s\S]*?)\[\/\1(?:_END)?\]/g;
        let match;
        data.blocks = [];
        while ((match = blockRegex.exec(text)) !== null) {
          const blockName = match[1];
          if (blockName.toLowerCase() === 'config') continue;
          const blockContent = match[2].trim();
          const items = {};
          const lines = blockContent.split('\n');
          lines.forEach(line => {
            const parts = line.split(':');
            if (parts.length >= 2) {
              const key = parts[0].trim();
              const value = parts.slice(1).join(':').trim();
              items[key] = value;
            }
          });
          data.blocks.push({ name: blockName, items: items });
        }
        return data;
      }

      function renderData(data) {
        if (!data.blocks || data.blocks.length === 0) {
          contentArea.innerHTML = '<div class="no-data">关系网数据读取失败.</div>';
          return;
        }
        contentArea.innerHTML = '';
        data.blocks.forEach(block => {
          const blockDiv = document.createElement('div');
          blockDiv.className = 'data-block';

          const avatarUrl = block.items['头像'] || '';

          let itemsHTML = `<img src="${avatarUrl}" alt="${block.name}" class="char-avatar">`;
          itemsHTML += '<div class="char-info">';
          itemsHTML += `<div class="data-block-title">${block.name}</div>`;

          for (const key in block.items) {
            if (key === '头像') continue;
            const value = block.items[key];
            if (key === '好感' || key === '病弱') {
              itemsHTML += `
                <div class="data-item">
                  <span class="data-key">${key}:</span>
                  <span class="data-value">${value}</span>
                </div>
                <div class="progress-bar-container">
                  <div class="progress-bar" style="width: ${value}%;"></div>
                </div>`;
            } else {
              itemsHTML += `
                <div class="data-item">
                  <span class="data-key">${key}:</span>
                  <span class="data-value">${value}</span>
                </div>`;
            }
          }
          itemsHTML += '</div>'; // close char-info
          blockDiv.innerHTML = itemsHTML;
          contentArea.appendChild(blockDiv);
        });
      }

      const rawData = dataContainer.textContent.trim();
      if (rawData) {
        const parsedData = parseData(rawData);
        renderData(parsedData);
      }
    });
    </script>
</body>
</html>
